local BaseEffect = import('Game.Chapter.NewChapterEffect.BaseEffect')
local base = BaseEffect

---@class CharacterNormalEffect : BaseEffect
local CharacterNormalEffect = Class("CharacterNormalEffect", BaseEffect)
local ResourceModule = CS.Engine.Modules.ResourceModule
local cs_coroutine = require 'XLua.cs_coroutine'
local Yielders = CS.Engine.Lib.Yielders
local KTool = CS.Engine.Lib.KTool
local NewChapterConstants = import('Game.Chapter.NewChapterConstants')

---以前特效加载一次之后  不会重新加载  为配合同一个特效要在同一时间加载到多个人身上的配置
local EffectIgnore = {
    [NewChapterConstants.CharacterEffect.TLSealOp01] = true,
    [NewChapterConstants.CharacterEffect.TLSealEd01] = true,
}


function CharacterNormalEffect:__init()
    self._isFinish = nil
    self._co = nil
    self.effectType = nil
    self.cacheLoader = {}
    self.cacheLoaderRes = {}
end

function CharacterNormalEffect:__delete()
    self._isFinish = nil
    self._co = nil
    self.effectType = nil
    self.cacheLoader = nil
    self.cacheLoaderRes = nil
end

---@param parameters NewChapter2DVo
function CharacterNormalEffect:Initialize(vo,effectType)
    base.StartEffect(self, vo)
    self.effectType = effectType
end

function CharacterNormalEffect:StartEffect(object)
    base.StartEffect(self, object)
    self.isFinish = false
    ---说明特效被加载过
    if not isNull(self.cacheLoader[self.effectType]) and isNull(self.cacheLoaderRes[object.name]) then
        if EffectIgnore[self.effectType] then
            local config = NewChapterConstants.CharacterBaseEffectConfig[self.effectType]
            local modelIns = self.cacheLoader[self.effectType]:Instantiate()
            KTool.ChangeAllLayer(modelIns, 17, 0)
            modelIns.transform:SetParent(object.transform)
            modelIns.transform.localPosition = config.Position
            modelIns.transform.localScale = config.Scale
            modelIns.transform.localRotation = CS.UnityEngine.Quaternion.identity
            self.cacheLoaderRes[object.name] = modelIns
        end
        self.isFinish = true
        return
    end
    self.co = cs_coroutine.start(function()
        local config = NewChapterConstants.CharacterBaseEffectConfig[self.effectType]
        if config then
            local loader = ResourceModule.LoadBundleAsync(config.Path, nil, true)
            while not loader.IsCompleted do
                coroutine.yield(Yielders.EndOfFrame)
            end

            if loader.IsSuccess then
                local modelIns = loader:Instantiate()
                KTool.ChangeAllLayer(modelIns, 17, 0)
                modelIns.transform:SetParent(object.transform)
                modelIns.transform.localPosition = config.Position
                modelIns.transform.localScale = config.Scale
                modelIns.transform.localRotation = CS.UnityEngine.Quaternion.identity
                self.cacheLoader[self.effectType] = loader
                self.cacheLoaderRes[object.name] = modelIns
                KTool.SetActive(modelIns.gameObject, true)
            else
                loader:Release()
            end

            self.isFinish = true
            self.co = nil
        else
            printError("sceneAin  id  %s  在 NewChapterConstants.SceneBaseEffectConfig 中没有配置！！！！")
        end
    end)
end

function CharacterNormalEffect:IsFinish()
    base.IsFinish(self)
    return true
end

function CharacterNormalEffect:EndEffect(object)
    base.EndEffect(self, object)
end

function CharacterNormalEffect:RemoveEffect(object)
    base.RemoveEffect(self, object)

    if self.cacheLoader[self.effectType] then
        self.cacheLoader[self.effectType]:Release()
        self.cacheLoader[self.effectType] = nil
    end

    if not isNull(self.cacheLoaderRes[object.name]) then
        KTool.SafeDelete(self.cacheLoaderRes[object.name])
        self.cacheLoaderRes[object.name] = nil
    end

end

return CharacterNormalEffect
